mapper.select:
select count(*) as total, avg(r.svr_satisfaction_score) as avgScore
from t_survey_response r
left join t_tal t on t.tal_id = r.svr_candidate_id
where 1 = 1

    and t.tal_company_id = #{companyId}


    and r.svr_template_id = #{templateId}


    and r.svr_submitted_at >= #{from}


    and r.svr_submitted_at <= #{to}

select round(r.svr_satisfaction_score) as bucket, count(*) as count
from t_survey_response r
left join t_tal t on t.tal_id = r.svr_candidate_id
where 1 = 1

    and t.tal_company_id = #{companyId}


    and r.svr_template_id = #{templateId}


    and r.svr_submitted_at >= #{from}


    and r.svr_submitted_at <= #{to}

group by round(r.svr_satisfaction_score)
order by bucket

select r.svr_id as responseId, r.svr_template_id as templateId, r.svr_candidate_id as candidateId, r.svr_satisfaction_score as satisfactionScore, cast(r.svr_answers as char) as answers, date_format(r.svr_submitted_at, '%Y-%m-%d %H:%i') as submittedAt, u.nick_name as candidateName, svt.svt_name as templateName from t_survey_response r left join t_tal t on t.tal_id = r.svr_candidate_id left join sys_user u on u.user_id = t.tal_user_id left join t_survey_template svt on svt.svt_id = r.svr_template_id where 1 = 1
and t.tal_company_id = #{companyId}
and r.svr_template_id = #{templateId}
and r.svr_submitted_at >= #{from}
and r.svr_submitted_at <= #{to}
order by r.svr_submitted_at desc

select count(*) as sentTotal,
       sum(case when d.svd_status = 0 then 1 else 0 end) as pendingTotal
from t_survey_dispatch d
where 1 = 1

    and d.svd_company_id = #{companyId}


    and d.svd_template_id = #{templateId}


    and d.svd_sent_at >= #{from}


    and d.svd_sent_at <= #{to}

select d.svd_id as dispatchId, d.svd_candidate_id as candidateId, cast(d.svd_link_token as char) as token, d.svd_status as status, date_format(d.svd_sent_at, '%Y-%m-%d %H:%i') as sentAt, date_format(d.svd_submitted_at, '%Y-%m-%d %H:%i') as submittedAt, u.nick_name as candidateName, svt.svt_name as templateName from t_survey_dispatch d left join t_tal t on t.tal_id = d.svd_candidate_id left join sys_user u on u.user_id = t.tal_user_id left join t_survey_template svt on svt.svt_id = d.svd_template_id where 1 = 1
and d.svd_company_id = #{companyId}
and d.svd_template_id = #{templateId}
and d.svd_sent_at >= #{from}
and d.svd_sent_at <= #{to}
order by d.svd_sent_at desc

select svt_id as templateId, svt_name as name, svt_trigger_scene as triggerScene, svt_company_id as companyId, cast(svt_questions as char) as questions, svt_status as status, date_format(svt_created_at, '%Y-%m-%d %H:%i') as createdAt from t_survey_template where (svt_company_id is null or svt_company_id = #{companyId})
and svt_status = #{status}
order by svt_id

mapper.update:
update t_survey_template
set svt_status = #{status}, svt_updated_at = now()
where svt_id = #{templateId}

update t_survey_dispatch
set svd_status = 1, svd_submitted_at = now()
where svd_id = #{dispatchId}
